"""Load the three grouping catalogs (read-only).

CL key = after first dash → Custom Label (not universal resolve_label).
Plain key = till last dash or whole SKU → SKU.
Packs key = whole SKU → Channel Child SKU.
"""

from __future__ import annotations

import csv
from dataclasses import dataclass, field
from typing import Mapping, Optional

from openpyxl import load_workbook

from shared import paths as wh
from shared.areeb_taxonomy import cell
from shared.cl_sku_match import key_after_first_dash, key_till_last_dash

PLAIN_SHEET = "Sheet1"
PACKS_SHEET = "01-Database"

SRC_CL = "cl"
SRC_PLAIN = "plain"
SRC_PACKS = "packs"


def _fold(value: object) -> str:
    return cell(value).casefold()


def _index_rows(rows: list[dict[str, str]], key_col: str) -> dict[str, dict[str, str]]:
    idx: dict[str, dict[str, str]] = {}
    for row in rows:
        key = _fold(row.get(key_col))
        if key and key not in idx:
            idx[key] = row
    return idx


def load_cl_index(path=None) -> dict[str, dict[str, str]]:
    csv_path = path or wh.cl_csv_path()
    with csv_path.open(encoding="utf-8-sig", newline="") as f:
        rows = [{k: cell(v) for k, v in row.items()} for row in csv.DictReader(f)]
    return _index_rows(rows, "Custom Label")


def load_xlsx_index(path, sheet: str, key_col: str) -> dict[str, dict[str, str]]:
    wb = load_workbook(path, read_only=True, data_only=True)
    try:
        ws = wb[sheet]
        it = ws.iter_rows(values_only=True)
        headers = [cell(h) for h in next(it)]
        rows: list[dict[str, str]] = []
        for raw in it:
            row = {
                headers[i]: cell(raw[i]) if i < len(raw) else ""
                for i in range(len(headers))
                if headers[i]
            }
            rows.append(row)
    finally:
        wb.close()
    return _index_rows(rows, key_col)


@dataclass
class Catalogs:
    cl: dict[str, dict[str, str]] = field(default_factory=dict)
    plain: dict[str, dict[str, str]] = field(default_factory=dict)
    packs: dict[str, dict[str, str]] = field(default_factory=dict)

    def lookup_cl(self, sku: object) -> Optional[dict[str, str]]:
        after = _fold(key_after_first_dash(sku))
        if after:
            return self.cl.get(after)
        return None

    def lookup_plain(self, sku: object) -> Optional[dict[str, str]]:
        till = _fold(key_till_last_dash(sku))
        if till and till in self.plain:
            return self.plain[till]
        whole = _fold(sku)
        if whole:
            return self.plain.get(whole)
        return None

    def lookup_packs(self, sku: object) -> Optional[dict[str, str]]:
        whole = _fold(sku)
        if whole:
            return self.packs.get(whole)
        return None

    def attribute_row(self, sku: object) -> tuple[Optional[str], Optional[Mapping[str, str]]]:
        """Packs whole → else CL after-first → else Plain. Separate from finish gate."""
        packs = self.lookup_packs(sku)
        if packs is not None:
            return SRC_PACKS, packs
        cl = self.lookup_cl(sku)
        if cl is not None:
            return SRC_CL, cl
        plain = self.lookup_plain(sku)
        if plain is not None:
            return SRC_PLAIN, plain
        return None, None


def load_catalogs() -> Catalogs:
    return Catalogs(
        cl=load_cl_index(),
        plain=load_xlsx_index(wh.plain_database_path(), PLAIN_SHEET, "SKU"),
        packs=load_xlsx_index(wh.packs_database_path(), PACKS_SHEET, "Channel Child SKU"),
    )

"""Order Grouping Sorter — dry-run grouping (no Packing Input write).

Locks: order-grouping-locks.md. SKU keys are not universal resolve_label.
"""

from __future__ import annotations

from collections import Counter, defaultdict
from dataclasses import dataclass, field
from datetime import date, datetime
from typing import Any, Callable, Iterable, Optional

from shared.areeb_taxonomy import cell
from shared.cl_sku_match import key_after_first_dash, key_till_last_dash  # noqa: F401 — grouping uses catalogs.py keys

from catalogs import SRC_CL, SRC_PACKS, SRC_PLAIN, Catalogs

LogFn = Callable[[str], None]

EXCLUDE_TAG = "post-order-designs"
RESEND_TAG = "1014-ALL-RESEND"
PRIME_TAG = "amazon prime order"
FAWAD_STORE = "mas clothing"
PLAIN_MARKERS = ("plainlg", "plain")

SHIFT_CAPS: tuple[tuple[str, str, int], ...] = (
    ("1st", "1st Shift", 300),
    ("2nd", "2nd Shift", 100),
    ("3rd", "3rd Shift", 100),
)

WAREHOUSE_STOCK = "Warehouse Stock"
IN_HOUSE = "In House Manufacture"
ON_DEMAND = "Supplier On Demand"

CSV_FIELDNAMES = [
    "Order #",
    "Ship By",
    "Quantity",
    "Item - Image URL",
    "Gift - Message",
    "Notes - From Buyer",
    "Item SKU",
    "Item Name",
    "Item - Options",
    "Recipient",
    "Tags",
]

# Graph left-side after ship-by + shift. Flag 0/x → slot x.
LEFT_FIELDS = (
    "order-source",
    "design-grouping",
    "shipping-service",
    "printing-method",
    "customised",
    "customisation-type",
    "print-size",
    "print-position",
    "supply-method",
    "supplier",
    "package-type",
)

CHAIN_PLAIN: tuple[tuple[str, int], ...] = (
    ("category", 30),
    ("product-type", 30),
    ("product-style", 30),
    ("department", 30),
    ("brand", 30),
    ("size", 30),
    ("colour", 30),
)
CHAIN_PRINTED: tuple[tuple[str, int], ...] = (
    ("category", 30),
    ("product-type", 30),
    ("product-style", 30),
    ("department", 1),
    ("brand", 0),
    ("size", 1),
    ("colour", 30),
)

ATTR_FIELD = {
    "category": "category",
    "product-type": "product_type",
    "product-style": "product_style",
    "department": "department",
    "brand": "brand",
    "size": "size",
    "colour": "colour",
}


def _fold(value: object) -> str:
    return cell(value).casefold()


def sku_is_plain_override(sku: object) -> bool:
    s = _fold(sku)
    return any(m in s for m in PLAIN_MARKERS)


def parse_qty(value: object) -> int:
    s = cell(value)
    if not s:
        return 0
    try:
        n = int(float(s))
    except ValueError:
        return 0
    return n if n > 0 else 0


def parse_ship_by(raw: object) -> Optional[date]:
    s = cell(raw)
    if not s:
        return None
    if len(s) >= 10 and s[4] == "-" and s[7] == "-":
        try:
            return date.fromisoformat(s[:10])
        except ValueError:
            return None
    return None


def slotify(value: object) -> str:
    s = _fold(value).replace(" ", "_")
    chars: list[str] = []
    for ch in s:
        if ch.isalnum() or ch in "-_":
            chars.append(ch)
        else:
            chars.append("_")
    out = "".join(chars).strip("_")
    while "__" in out:
        out = out.replace("__", "_")
    return out or "x"


def date_slot(ship: date, run: date) -> str:
    return "today" if ship <= run else ship.isoformat()


@dataclass
class LineAttrs:
    sku: str
    qty: int
    finish: Optional[str]
    source: Optional[str]
    supply_method: str = ""
    supplier: str = ""
    printing_type: str = ""
    customise: str = ""
    category: str = ""
    product_type: str = ""
    product_style: str = ""
    department: str = ""
    brand: str = ""
    size: str = ""
    colour: str = ""


@dataclass
class Order:
    number: str
    ship_by_raw: str
    ship_by: Optional[date]
    tag_names: list[str]
    store_name: str
    lines: list[LineAttrs] = field(default_factory=list)
    unmatched_reason: str = ""

    @property
    def line_count(self) -> int:
        return len(self.lines)

    @property
    def units(self) -> int:
        return sum(ln.qty for ln in self.lines)


@dataclass
class ProcessBin:
    shift_slot: str
    shift_folder: str
    process_name: str
    orders: list[Order]


@dataclass
class SortResult:
    run_date: date
    skipped_post: int
    empty_skipped: int
    resend: list[Order]
    unmatched: list[Order]
    held: list[Order]
    bins: list[ProcessBin]
    pool_orders: int


def _item_is_skipped(item: dict[str, Any]) -> bool:
    if item.get("adjustment") is True:
        return True
    name = _fold(item.get("name"))
    return "discount" in name


def _tag_names(tag_ids: Any, tag_id_to_name: dict[int, str]) -> list[str]:
    if not isinstance(tag_ids, list):
        return []
    names: list[str] = []
    for tid in tag_ids:
        try:
            key = int(tid)
        except (TypeError, ValueError):
            continue
        name = cell(tag_id_to_name.get(key))
        if name:
            names.append(name)
    return names


def _has_tag(names: Iterable[str], want: str) -> bool:
    w = want.casefold()
    return any(n.casefold() == w for n in names)


def _store_name(order: dict[str, Any], store_id_to_name: dict[int, str]) -> str:
    adv = order.get("advancedOptions")
    sid = None
    if isinstance(adv, dict):
        sid = adv.get("storeId")
    if sid is None:
        sid = order.get("storeId")
    try:
        return cell(store_id_to_name.get(int(sid)))
    except (TypeError, ValueError):
        return ""


def finish_for_sku(sku: object, catalogs: Catalogs) -> Optional[str]:
    if sku_is_plain_override(sku):
        return "plain"
    if catalogs.lookup_cl(sku) is not None:
        return "printed"
    if catalogs.lookup_plain(sku) is not None:
        return "plain"
    if catalogs.lookup_packs(sku) is not None:
        return "plain"
    return None


def _row_brand_size_colour(source: str, row: Mapping[str, str]) -> tuple[str, str, str]:
    if source == SRC_PACKS:
        return cell(row.get("Brand Name")), cell(row.get("Pack Size")), ""
    return cell(row.get("Brand")), cell(row.get("Size")), cell(row.get("Colour"))


def attrs_for_sku(sku: object, qty: int, catalogs: Catalogs) -> LineAttrs:
    finish = finish_for_sku(sku, catalogs)
    source, row = catalogs.attribute_row(sku)
    if row is None:
        return LineAttrs(sku=cell(sku), qty=qty, finish=finish, source=None)
    brand, size, colour = _row_brand_size_colour(source or "", row)
    return LineAttrs(
        sku=cell(sku),
        qty=qty,
        finish=finish,
        source=source,
        supply_method=cell(row.get("Supply Method")),
        supplier=cell(row.get("Supplier Name")),
        printing_type=cell(row.get("Printing Type")),
        customise=cell(row.get("Customise")),
        category=cell(row.get("Category (Areeb)")),
        product_type=cell(row.get("Product Type (Areeb)")),
        product_style=cell(row.get("Product Style (Areeb)")),
        department=cell(row.get("Department (Areeb)")),
        brand=brand,
        size=size,
        colour=colour,
    )


def orders_from_ss(
    raw_orders: list[dict[str, Any]],
    tag_id_to_name: dict[int, str],
    store_id_to_name: dict[int, str],
    catalogs: Catalogs,
) -> tuple[list[Order], int, int]:
    """Skip post-order-designs and discount/adjustment lines. Attach catalog attrs."""
    out: list[Order] = []
    skipped_post = 0
    empty_skipped = 0
    for raw in raw_orders:
        names = _tag_names(raw.get("tagIds"), tag_id_to_name)
        if _has_tag(names, EXCLUDE_TAG):
            skipped_post += 1
            continue
        items = raw.get("items")
        if not isinstance(items, list):
            empty_skipped += 1
            continue
        lines: list[LineAttrs] = []
        for item in items:
            if not isinstance(item, dict) or _item_is_skipped(item):
                continue
            sku = cell(item.get("sku"))
            qty = parse_qty(item.get("quantity"))
            lines.append(attrs_for_sku(sku, qty, catalogs))
        if not lines:
            empty_skipped += 1
            continue
        out.append(
            Order(
                number=cell(raw.get("orderNumber")),
                ship_by_raw=cell(raw.get("shipByDate")),
                ship_by=parse_ship_by(raw.get("shipByDate")),
                tag_names=names,
                store_name=_store_name(raw, store_id_to_name),
                lines=lines,
            )
        )
    return out, skipped_post, empty_skipped


def order_source_slot(store_name: str) -> str:
    if _fold(store_name) == FAWAD_STORE:
        return "fawad"
    return "own"


def prime_slot(tag_names: list[str]) -> str:
    return "prime" if _has_tag(tag_names, PRIME_TAG) else "non-prime"


def customised_slot(value: str) -> str:
    return "customised" if _fold(value) == "yes" else "readymade"


def _unanimous(values: list[str]) -> Optional[str]:
    nonempty = [v for v in values if v]
    if not nonempty:
        return None
    first = nonempty[0]
    if all(v == first for v in nonempty):
        return first
    return None


def _field_values(order: Order, field: str) -> list[str]:
    attr = ATTR_FIELD[field]
    vals: list[str] = []
    for ln in order.lines:
        if field == "colour" and ln.source == SRC_PACKS:
            continue
        vals.append(getattr(ln, attr))
    return vals


def order_skips_colour(order: Order) -> bool:
    return bool(order.lines) and all(ln.source == SRC_PACKS for ln in order.lines)


def _printed_lines(order: Order) -> list[LineAttrs]:
    return [ln for ln in order.lines if ln.finish == "printed"]


def _order_finish(order: Order) -> Optional[str]:
    finishes = [ln.finish for ln in order.lines]
    if any(f is None for f in finishes):
        return None
    if "printed" in finishes:
        return "printed"
    return "plain"


def _printed_tail(supply: str) -> str:
    """warehouse-stock / in-house share supplier slot x; on-demand splits supplier."""
    if supply == ON_DEMAND:
        return "on-demand"
    return "warehouse-stock"


def left_slots(order: Order, finish: str) -> Optional[list[str]]:
    """Graph slots after date + shift. None → unmatched (reason set)."""
    supply_vals = [ln.supply_method for ln in order.lines]
    if any(not v for v in supply_vals):
        order.unmatched_reason = "blank supply-method"
        return None
    supply = _unanimous(supply_vals)
    if supply is None:
        order.unmatched_reason = "mixed supply-method"
        return None
    if finish == "plain" and supply == IN_HOUSE:
        order.unmatched_reason = "plain in-house"
        return None

    supplier_flag_value = True
    if finish == "printed" and _printed_tail(supply) == "warehouse-stock":
        supplier_flag_value = False

    if supplier_flag_value:
        sup_vals = [ln.supplier for ln in order.lines]
        if any(not v for v in sup_vals):
            order.unmatched_reason = "blank supplier"
            return None
        supplier = _unanimous(sup_vals)
        if supplier is None:
            order.unmatched_reason = "mixed supplier"
            return None
        supplier_slot = slotify(supplier)
    else:
        supplier_slot = "x"

    if finish == "printed":
        printed = _printed_lines(order)
        if not printed:
            order.unmatched_reason = "printed-wins with no printed lines"
            return None
        pt_vals = [ln.printing_type for ln in printed]
        if any(not v for v in pt_vals):
            order.unmatched_reason = "blank printing-method"
            return None
        printing = _unanimous(pt_vals)
        if printing is None:
            order.unmatched_reason = "mixed printing-method"
            return None
        cust_vals = [customised_slot(ln.customise) for ln in printed]
        customised = _unanimous(cust_vals)
        if customised is None:
            order.unmatched_reason = "mixed customised"
            return None
        print_slot = slotify(printing)
        cust_slot = customised
    else:
        print_slot = "x"
        cust_slot = "x"

    return [
        finish,
        order_source_slot(order.store_name),
        "x",  # design-grouping
        prime_slot(order.tag_names),
        print_slot,
        cust_slot,
        "x",  # customisation-type
        "x",  # print-size
        "x",  # print-position
        slotify(supply),
        supplier_slot,
        "x",  # package-type
    ]


def _mark_unmatched(order: Order, reason: str) -> None:
    if not order.unmatched_reason:
        order.unmatched_reason = reason


def _split_flag1(orders: list[Order], field: str) -> tuple[list[Order], dict[str, list[Order]]]:
    unmatched: list[Order] = []
    groups: dict[str, list[Order]] = defaultdict(list)
    for order in orders:
        vals = _field_values(order, field)
        if not vals or any(not v for v in vals):
            _mark_unmatched(order, f"blank {field}")
            unmatched.append(order)
            continue
        u = _unanimous(vals)
        if u is None:
            _mark_unmatched(order, f"mixed {field}")
            unmatched.append(order)
            continue
        groups[u].append(order)
    return unmatched, groups


def _split_flag30(orders: list[Order], field: str) -> tuple[list[Order], dict[str, list[Order]], list[Order]]:
    unmatched: list[Order] = []
    unanimous: dict[str, list[Order]] = defaultdict(list)
    mixed: list[Order] = []
    for order in orders:
        vals = _field_values(order, field)
        if any(not v for v in vals):
            _mark_unmatched(order, f"blank {field}")
            unmatched.append(order)
            continue
        u = _unanimous(vals) if vals else None
        if u is None:
            mixed.append(order)
            continue
        unanimous[u].append(order)
    return unmatched, unanimous, mixed


def peel_chain(
    orders: list[Order],
    chain: tuple[tuple[str, int], ...],
    prefix: list[str],
    unmatched: list[Order],
) -> list[tuple[list[str], list[Order]]]:
    if not orders:
        return []
    if not chain:
        return [(prefix, orders)]
    field, flag = chain[0]
    rest = chain[1:]

    if field == "colour":
        skip = [o for o in orders if order_skips_colour(o)]
        need = [o for o in orders if not order_skips_colour(o)]
        out: list[tuple[list[str], list[Order]]] = []
        if skip:
            out.extend(peel_chain(skip, rest, prefix, unmatched))
        if need:
            out.extend(peel_chain(need, chain, prefix, unmatched) if False else _peel_one(need, field, flag, rest, prefix, unmatched))
        return out
    return _peel_one(orders, field, flag, rest, prefix, unmatched)


def _peel_one(
    orders: list[Order],
    field: str,
    flag: int,
    rest: tuple[tuple[str, int], ...],
    prefix: list[str],
    unmatched: list[Order],
) -> list[tuple[list[str], list[Order]]]:
    if flag == 0:
        return peel_chain(orders, rest, prefix + ["x"], unmatched)
    if flag == 1:
        bad, groups = _split_flag1(orders, field)
        unmatched.extend(bad)
        out: list[tuple[list[str], list[Order]]] = []
        for val, group in groups.items():
            out.extend(peel_chain(group, rest, prefix + [slotify(val)], unmatched))
        return out
    # flag 30
    bad, unanimous, mixed = _split_flag30(orders, field)
    unmatched.extend(bad)
    leftover: list[Order] = list(mixed)
    out: list[tuple[list[str], list[Order]]] = []
    for val, group in unanimous.items():
        units = sum(o.units for o in group)
        if units >= 30:
            out.extend(peel_chain(group, rest, prefix + [slotify(val)], unmatched))
        else:
            leftover.extend(group)
    if leftover:
        out.extend(peel_chain(leftover, rest, prefix, unmatched))
    return out


def _process_name(date_s: str, shift_s: str, slots: list[str]) -> str:
    return "-".join([date_s, shift_s, *slots])


def _fill_shifts(orders: list[Order], run: date) -> tuple[list[list[Order]], list[Order]]:
    def sort_key(o: Order) -> tuple:
        d = o.ship_by
        assert d is not None
        return (d > run, d, o.number)

    ranked = sorted(orders, key=sort_key)
    assigned: list[list[Order]] = [[] for _ in SHIFT_CAPS]
    remaining = [cap for _, _, cap in SHIFT_CAPS]
    held: list[Order] = []
    shift_i = 0
    for order in ranked:
        placed = False
        while shift_i < len(SHIFT_CAPS):
            if order.line_count <= remaining[shift_i]:
                assigned[shift_i].append(order)
                remaining[shift_i] -= order.line_count
                placed = True
                break
            shift_i += 1
        if not placed:
            held.append(order)
    return assigned, held


def group_orders(orders: list[Order], run: date) -> SortResult:
    resend: list[Order] = []
    unmatched: list[Order] = []
    eligible: list[Order] = []
    for order in orders:
        if _has_tag(order.tag_names, RESEND_TAG):
            resend.append(order)
            continue
        if order.ship_by is None:
            _mark_unmatched(order, "blank ship-by" if not order.ship_by_raw else "unparseable ship-by")
            unmatched.append(order)
            continue
        finish = _order_finish(order)
        if finish is None:
            _mark_unmatched(order, "no catalog match")
            unmatched.append(order)
            continue
        slots = left_slots(order, finish)
        if slots is None:
            unmatched.append(order)
            continue
        order._finish = finish  # type: ignore[attr-defined]
        order._left = slots  # type: ignore[attr-defined]
        eligible.append(order)

    assigned, held = _fill_shifts(eligible, run)
    bins: list[ProcessBin] = []
    for (shift_slot, shift_folder, _), shift_orders in zip(SHIFT_CAPS, assigned):
        by_key: dict[tuple[str, tuple[str, ...]], list[Order]] = defaultdict(list)
        for order in shift_orders:
            dslot = date_slot(order.ship_by, run)  # type: ignore[arg-type]
            left = tuple(order._left)  # type: ignore[attr-defined]
            by_key[(dslot, left)].append(order)
        for (dslot, left), group in by_key.items():
            finish = group[0]._finish  # type: ignore[attr-defined]
            chain = CHAIN_PLAIN if finish == "plain" else CHAIN_PRINTED
            peeled_unmatched: list[Order] = []
            parts = peel_chain(group, chain, list(left), peeled_unmatched)
            unmatched.extend(peeled_unmatched)
            for slots, part_orders in parts:
                bins.append(
                    ProcessBin(
                        shift_slot=shift_slot,
                        shift_folder=shift_folder,
