) -> SortResult:
    parsed, skipped_post, empty_skipped = orders_from_ss(
        raw_orders, tag_id_to_name, store_id_to_name, catalogs
    )
    result = group_orders(parsed, run_date)
    result.skipped_post = skipped_post
    result.empty_skipped = empty_skipped
    result.pool_orders = len(parsed) + skipped_post + empty_skipped
    return result


