def write_csv(path: Path, rows: list[dict[str, str]]) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        with path.open("w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=CSV_FIELDNAMES)
            writer.writeheader()
            writer.writerows(rows)
        return path
    except PermissionError:
        # ponytail: Excel/Cursor lock — same fallback as CL csv-writes.
        fallback = path.with_name(path.stem + "_write_fallback" + path.suffix)
        with fallback.open("w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=CSV_FIELDNAMES)
            writer.writeheader()
            writer.writerows(rows)
        return fallback


def write_process_csvs(
    result: SortResult,
    *,
    input_root: Path | None = None,
) -> list[Path]:
    """One CSV per process into Packing Input/{DD-MM-YYYY}/{shift}/. Held is not written."""
    root = Path(input_root) if input_root else wh.packing_input_dir()
    date_folder = input_date_folder(result.run_date)
    for _, folder, _ in SHIFT_CAPS:
        (root / date_folder / folder).mkdir(parents=True, exist_ok=True)
    written: list[Path] = []

    def dump(folder: str, name: str, orders: list[Order]) -> None:
        ordered = _orders_in_part_order(orders)
        if not ordered:
            return
        path = root / date_folder / folder / f"{name}.csv"
        written.append(
            write_csv(path, [row for order in ordered for row in _csv_rows_for(order)])
        )

    dump(SPECIAL_SHIFT_FOLDER, "resend", result.resend)
    dump(SPECIAL_SHIFT_FOLDER, "unmatched", result.unmatched)
    for bin_ in result.bins:
        dump(bin_.shift_folder, bin_.process_name, bin_.orders)

    keep = {p.resolve() for p in written}
    for _, folder, _ in SHIFT_CAPS:
        shift_dir = root / date_folder / folder
        for old in shift_dir.glob("*.csv"):
            if old.resolve() in keep:
                continue
            try:
                old.unlink()
            except PermissionError:
                pass
    return written

def _process_name(date_s: str, shift_s: str, slots: list[str]) -> str:
    return "-".join([date_s, shift_s, *slots])


# Floor CSV numbers the packing line already uses. Same Graph fields classify
# the order; these families take the numeric filename and skip the 30-chain.
# Leftover (plain, Gildan, stickers, mugs, unnamed Fawad variants, …) still
# uses Graph names + 30-chain. More families when the supervisor names them.
NAMED_CODES: dict[str, tuple[str, str, str]] = {
    "fawad_ss_fotl_rm": ("80", "280", "380"),
    "own_ss_fotl_rm": ("100", "200", "300"),
    "own_ironon_rm": ("1000", "2000", "3000"),
    "fawad_ironon_rm": ("1080", "2080", "3080"),
    "own_ss_fotl_per": ("4000", "4200", "4300"),
    "own_ironon_per": ("5000", "5200", "5300"),
    "fawad_ironon_per": ("5080", "5280", "5380"),
    "own_ss_fotl_rm_prime": ("8000", "8200", "8300"),
    "own_ss_fotl_per_prime": ("8060", "8260", "8360"),
}
SHIFT_CODE_INDEX = {"1st": 0, "2nd": 1, "3rd": 2}


def _line_is_ss_fotl(ln: LineAttrs) -> bool:
    if _fold(ln.supply_method) != _fold(WAREHOUSE_STOCK):
        return False
    if _fold(ln.category) != "t-shirts":
        return False
    pt = _fold(ln.product_type)
    if not pt:
        return False
    if "long sleeve" in pt or "longsleeve" in pt:
        return False
    return "short sleeve" in pt or "t-shirt" in pt


def _line_is_iron_on(ln: LineAttrs) -> bool:
    if _fold(ln.supply_method) != _fold(IN_HOUSE):
        return False
    cat = _fold(ln.category)
    pt = _fold(ln.product_type)
    if "sticker" in cat or "sticker" in pt:
        return False
    return cat == "iron-on" or "iron-on" in pt or "iron on" in pt


def _all_chain(order: Order, pred) -> bool:
    lines = _chain_lines(order)
    return bool(lines) and all(pred(ln) for ln in lines)


def named_family(order: Order) -> Optional[str]:
    """NAMED_CODES key, or None to keep the Graph filename + 30-chain."""
    left = order.left
    if len(left) < 10:
        return None
    finish, source, _, prime, printing, cust = left[:6]
    supply = left[9]
    if finish != "printed" or printing != "dtf":
        return None
    if supply == slotify(WAREHOUSE_STOCK) and _all_chain(order, _line_is_ss_fotl):
        if source == "fawad" and prime == "non-prime" and cust == "readymade":
            return "fawad_ss_fotl_rm"
        if source == "own" and prime == "non-prime" and cust == "readymade":
            return "own_ss_fotl_rm"
        if source == "own" and prime == "prime" and cust == "readymade":
            return "own_ss_fotl_rm_prime"
        if source == "own" and prime == "non-prime" and cust == "customised":
            return "own_ss_fotl_per"
        if source == "own" and prime == "prime" and cust == "customised":
            return "own_ss_fotl_per_prime"
        return None
    if supply == slotify(IN_HOUSE) and _all_chain(order, _line_is_iron_on):
        # Iron-on floor codes do not split Prime (manual 1000 was mostly Prime Letter).
        if source == "fawad" and cust == "readymade":
            return "fawad_ironon_rm"
        if source == "fawad" and cust == "customised":
            return "fawad_ironon_per"
        if source == "own" and cust == "readymade":
            return "own_ironon_rm"
        if source == "own" and cust == "customised":
            return "own_ironon_per"
        return None
    return None


def named_process_code(order: Order, shift_slot: str) -> Optional[str]:
    family = named_family(order)
    if family is None:
        return None
    return NAMED_CODES[family][SHIFT_CODE_INDEX[shift_slot]]


def _bin_sort_key(b: ProcessBin) -> tuple:
    shift_i = ["1st", "2nd", "3rd"].index(b.shift_slot)
    if b.process_name.isdigit():
        return (shift_i, 0, int(b.process_name))
    return (shift_i, 1, b.process_name)

